// ResidualInfo describes one non-blank residual span of a file.
type ResidualInfo struct {
	StartLine int    `json:"start_line"`
	EndLine   int    `json:"end_line"`
	FirstLine string `json:"first_line"`
	Reason    Reason `json:"reason"`
}

// Totals sums the file outcomes of a report.
type Totals struct {
	Files           int            `json:"files"`
	Adopted         int            `json:"adopted"`
	Skipped         int            `json:"skipped"`
	Rejected        int            `json:"rejected"`
	Units           int            `json:"units"`
	SkippedByReason map[Reason]int `json:"skipped_by_reason"`
}

// Report is the adoption report for one run of sedum adopt.
type Report struct {
	Files     []FileReport `json:"files"`
	Totals    Totals       `json:"totals"`
	Recording string       `json:"recording,omitempty"`
}

// NewReport returns an empty report ready for Add.
func NewReport() *Report {
	return &Report{Files: []FileReport{}, Totals: Totals{SkippedByReason: map[Reason]int{}}}
}

// Add records one file's outcome and updates the totals.
func (r *Report) Add(f FileReport) {
	r.Files = append(r.Files, f)
	r.Totals.Files++
	r.Totals.Units += f.Units
	switch f.Status {
	case StatusAdopted:
		r.Totals.Adopted++
	case StatusSkipped:
		r.Totals.Skipped++
	case StatusRejected:
		r.Totals.Rejected++
	}
	if (f.Status == StatusSkipped || f.Status == StatusRejected) && f.Reason != "" {
		r.Totals.SkippedByReason[f.Reason]++
	}
}

// JSON returns the report as indented JSON with a trailing newline.
func (r *Report) JSON() ([]byte, error) {
	b, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal report: %w", err)
	}
	return append(b, '\n'), nil
}

// ResidualsOf reports the non-blank residual spans of a file, classifying each
// as a header, a floating comment, or other residual text.
func ResidualsOf(src []byte, spans []Span, comment genpkg.Comment) []ResidualInfo {
	var out []ResidualInfo
	line := 1
	first := true
	unitSeen := false
	for _, s := range spans {
		isFirst := first && s.Kind != KindHeader
		if s.Kind != KindHeader {
			first = false
		}
		if s.Kind == KindUnit {
			unitSeen = true
		}
		if s.Kind == KindResidual && !ResidualIsBlank(s) {
			lines := strings.Split(s.Text, "\n")
			start, end := -1, -1
			allComment := comment.Prefix != ""
			for i, l := range lines {
				if strings.TrimSpace(l) == "" {
					continue
				}
				if start < 0 {
					start = i
				}
				end = i
				if !strings.HasPrefix(strings.TrimLeft(l, " \t"), comment.Prefix) {
					allComment = false
				}
			}
			reason := ReasonOtherResidual
			if allComment && isFirst && !unitSeen {
				reason = ReasonHeader
			} else if allComment {
				reason = ReasonFloatingComment
			}
			out = append(out, ResidualInfo{
				StartLine: line + start,
				EndLine:   line + end,
				FirstLine: strings.TrimSpace(lines[start]),
				Reason:    reason,
			})
		}
		line += strings.Count(s.Text, "\n")
	}
	return out
}

// Text returns a plain-text summary of the report.
func (r *Report) Text() string {
	var b strings.Builder
	fmt.Fprintf(&b, "adopt: %d file(s): %d adopted, %d skipped, %d rejected, %d unit(s)\n", r.Totals.Files, r.Totals.Adopted, r.Totals.Skipped, r.Totals.Rejected, r.Totals.Units)
	if r.Totals.Skipped+r.Totals.Rejected > 0 {
		b.WriteString("skipped by reason:\n")
		var reasons []string
		for k := range r.Totals.SkippedByReason {
			reasons = append(reasons, string(k))
		}
		sort.Strings(reasons)
		for _, k := range reasons {
			fmt.Fprintf(&b, "  %s: %d\n", k, r.Totals.SkippedByReason[Reason(k)])
		}
		for _, k := range reasons {
			fmt.Fprintf(&b, "%s:\n", k)
			for _, f := range r.Files {
				if (f.Status != StatusSkipped && f.Status != StatusRejected) || string(f.Reason) != k {
					continue
				}
				if len(f.Residuals) == 0 {
					fmt.Fprintf(&b, "  %s\n", f.Path)
				}
				if len(f.Residuals) == 1 {
					res := f.Residuals[0]
					fmt.Fprintf(&b, "  %s (lines %d-%d: %s)\n", f.Path, res.StartLine, res.EndLine, res.FirstLine)
				}
				if len(f.Residuals) > 1 {
					for _, res := range f.Residuals {
						fmt.Fprintf(&b, "  %s lines %d-%d: %s\n", f.Path, res.StartLine, res.EndLine, res.FirstLine)
					}
				}
			}
		}
	}
	var order []string
	byRecord := map[string][]string{}
	for _, f := range r.Files {
		if f.Status != StatusAdopted || f.Record == "" {
			continue
		}
		if _, ok := byRecord[f.Record]; !ok {
			order = append(order, f.Record)
		}
		byRecord[f.Record] = append(byRecord[f.Record], f.Path)
	}
	if len(order) > 0 {
		b.WriteString("list the adopted files in their imprints so grow --check sees them:\n")
		for _, id := range order {
			fmt.Fprintf(&b, "  provenance edit %s", id)
			for _, p := range byRecord[id] {
				fmt.Fprintf(&b, " --add-scope %s", p)
			}
			b.WriteString("\n")
		}
	}
	if r.Recording != "" {
		fmt.Fprintf(&b, "recording: %s\n", r.Recording)
	}
	return b.String()
}

func TestReportTotals(t *testing.T) {
	r := NewReport()
	r.Add(FileReport{Path: "a.go", Status: StatusAdopted, Units: 3})
	r.Add(FileReport{Path: "b.go", Status: StatusSkipped, Reason: ReasonHeader})
	r.Add(FileReport{Path: "c.go", Status: StatusSkipped, Reason: ReasonHeader})
	r.Add(FileReport{Path: "d.go", Status: StatusRejected, Reason: ReasonOtherResidual})
	tot := r.Totals
	if tot.Files != 4 || tot.Adopted != 1 || tot.Skipped != 2 || tot.Rejected != 1 || tot.Units != 3 {
		t.Errorf("totals = %+v", tot)
	}
	want := map[Reason]int{ReasonHeader: 2, ReasonOtherResidual: 1}
	if len(tot.SkippedByReason) != len(want) {
		t.Errorf("SkippedByReason = %v, want %v", tot.SkippedByReason, want)
	}
	for k, v := range want {
		if tot.SkippedByReason[k] != v {
			t.Errorf("SkippedByReason[%s] = %d, want %d", k, tot.SkippedByReason[k], v)
		}
	}
}

func TestReportJSONKeys(t *testing.T) {
	r := NewReport()
	r.Add(FileReport{Path: "a.go", Status: StatusAdopted, Units: 1})
	b, err := r.JSON()
	if err != nil {
		t.Fatal(err)
	}
	s := string(b)
	for _, want := range []string{`"skipped_by_reason": {}`, `"status": "adopted"`} {
		if !strings.Contains(s, want) {
			t.Errorf("JSON missing %s:\n%s", want, s)
		}
	}
	if !strings.HasSuffix(s, "\n") {
		t.Errorf("JSON does not end with a newline")
	}
	if strings.Contains(s, "timestamp") {
		t.Errorf("JSON has a timestamp field:\n%s", s)
	}
}

func TestResidualsOf(t *testing.T) {
	src := []byte("# licence\nimport os\n\ndef f():\n    pass\n\n# note\nx = 1\n")
	spans := []Span{
		{Kind: KindResidual, Text: "# licence\n"},
		{Kind: KindResidual, Text: "import os\n\n"},
		{Kind: KindUnit, Text: "def f():\n    pass\n", Action: "setFunction"},
		{Kind: KindResidual, Text: "\n# note\n"},
		{Kind: KindResidual, Text: "x = 1\n"},
	}
	got := ResidualsOf(src, spans, genpkg.Comment{Prefix: "#"})
	want := []ResidualInfo{
		{StartLine: 1, EndLine: 1, FirstLine: "# licence", Reason: ReasonHeader},
		{StartLine: 2, EndLine: 2, FirstLine: "import os", Reason: ReasonOtherResidual},
		{StartLine: 7, EndLine: 7, FirstLine: "# note", Reason: ReasonFloatingComment},
		{StartLine: 8, EndLine: 8, FirstLine: "x = 1", Reason: ReasonOtherResidual},
	}
	if len(got) != len(want) {
		t.Fatalf("got %d residuals, want %d: %+v", len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("residual %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

func TestResidualsOfEmptyPrefix(t *testing.T) {
	src := []byte("# licence\nimport os\n\ndef f():\n    pass\n\n# note\nx = 1\n")
	spans := []Span{
		{Kind: KindResidual, Text: "# licence\n"},
		{Kind: KindResidual, Text: "import os\n\n"},
		{Kind: KindUnit, Text: "def f():\n    pass\n", Action: "setFunction"},
		{Kind: KindResidual, Text: "\n# note\n"},
		{Kind: KindResidual, Text: "x = 1\n"},
	}
	got := ResidualsOf(src, spans, genpkg.Comment{})
	if len(got) != 4 {
		t.Fatalf("got %d residuals, want 4: %+v", len(got), got)
	}
	for i, res := range got {
		if res.Reason != ReasonOtherResidual {
			t.Errorf("residual %d reason = %s, want %s", i, res.Reason, ReasonOtherResidual)
		}
	}
}

